const payload = {source_row_id:"TP01", action:"create_practice_contact", company:"Lipa Analitika", contact:"Ana Sever", email:"ana@lipa.test"};
const base = {payload, approvedPayload:payload, decision:"approve", actor:"reviewer.test", allowedActor:"reviewer.test", expired:false, completed:false};
return [
  {json:{...base, scenario:"approved"}},
  {json:{...base, scenario:"rejected",decision:"reject"}},
  {json:{...base, scenario:"changed",payload:{...payload,email:"changed@lipa.test"}}},
  {json:{...base, scenario:"expired",expired:true}},
  {json:{...base, scenario:"repeated",completed:true}},
  {json:{...base, scenario:"wrong_identity",actor:"other.test"}}
];

function canonical(x) { if (Array.isArray(x)) return "["+x.map(canonical).join(",")+"]"; if(x && typeof x==="object") return "{"+Object.keys(x).sort().map(k=>JSON.stringify(k)+":"+canonical(x[k])).join(",")+"}"; return JSON.stringify(x); }
return $input.all().map(item => {
 const x=item.json;
 let status;
 if(x.actor!==x.allowedActor) status="denied_identity";
 else if(x.decision==="reject") status="rejected";
 else if(x.expired) status="expired";
 else if(x.decision!=="approve") status="awaiting_approval";
 else if(canonical(x.payload)!==canonical(x.approvedPayload)) status="needs_new_approval";
 else if(x.completed) status="already_completed";
 else status="simulated_ready";
 return {json:{scenario:x.scenario,status,externalActionPerformed:false,payload:x.payload,
  note:"Lokalna ucna vaja. Identiteta in stanje sta izmisljena vhodna podatka; noben CRM ali sporocilo ni spremenjeno."}};
});
